// Build fiscal dominance summary
const score = $('Fiscal Score').first().json;
const stress = $('Stress Scenarios').first().json;
const banking = $('Banking Stress').first().json;
const fomc = $('FOMC Cascade').first().json;

const dominanceScore = score?.dominance_score || 50;
const regime = dominanceScore > 70 ? 'HIGH' : dominanceScore > 50 ? 'MODERATE' : 'LOW';
const flips = fomc?.aggregate?.flip_count || 0;
const mortgage = score?.mortgage_rate?.current || 0;
const kreDrawdown = banking?.kre_drawdown_pct || 0;

let alertLevel = 'NORMAL';
let alertColor = '🟢';
if (dominanceScore > 70) { alertLevel = 'CRITICAL'; alertColor = '🔴'; }
else if (dominanceScore > 55) { alertLevel = 'ELEVATED'; alertColor = '🟡'; }

const summary = `${alertColor} Fiscal Dominance: ${regime} (${dominanceScore.toFixed(0)})\n` +
  `10Y: ${(score?.ten_year_yield || 0).toFixed(2)}% | Mortgage: ${mortgage.toFixed(2)}%\n` +
  `KRE drawdown: ${kreDrawdown.toFixed(1)}% | FOMC flips: ${flips}\n` +
  `Trilemma: ${fomc?.trilemma?.most_likely_outcome || 'data-dependent'}`;

return [{
  json: {
    timestamp: new Date().toISOString(),
    dominance_score: dominanceScore,
    regime,
    alert_level: alertLevel,
    ten_year_yield: score?.ten_year_yield || 0,
    mortgage_rate: mortgage,
    kre_drawdown: kreDrawdown,
    fomc_flips: flips,
    fomc_aggregate: fomc?.aggregate || {},
    stress_scenarios: stress?.scenarios || [],
    banking: banking || {},
    summary,
    is_alert: dominanceScore > 60 || flips > 0
  }
}];
